    "Apple": {revenue:382, total:416.2, people:45.85, profit:67.04, conf:"derived",
      scope:"Device sales ($307.0B) plus $75.0B Foxconn pays Apple for buy-sell components; services excluded", period:"FY2025 (Sep 29, 2024 – Sep 27, 2025); Foxconn flows are Hon Hai calendar 2025",
      revenueLabel:"device sales plus buy-sell receipts", otherLabel:"Other suppliers & production",
      outside:[{label:"Buyers in Americas", usd:131.6}, {label:"Buyers in Europe, India, Middle East & Africa", usd:81.9}, {label:"Buyers in Greater China", usd:47.5}, {label:"Buyers in Japan", usd:21.2}, {label:"Buyers in Rest of Asia Pacific", usd:24.9}],
      basis:"FY2025 10-K: Products net sales $307.0B of $416.2B total. Products cost of sales $194.1B gives a products gross margin of $112.9B (36.8%). R&D plus SG&A ($34.55B + $27.60B = $62.15B) is split by products' 73.8% share of net sales: $45.85B goes to products, leaving $67.04B products operating profit. Services keep $66.01B, and the two add back to the reported $133.05B. Inflow is $382.0B = $307.0B from device customers (the five segments scaled by 73.8%; Apple says Greater China is somewhat more iPhone-heavy, so that region is slightly understated) plus $75.0B Foxconn pays Apple for components resold under buy-sell. That $75.0B is Hon Hai Vendor L, NT$2,348.1B at 31.3. Apple does not record it as net sales but receives it in cash, and the gross Apple->Foxconn $114B invoice includes it. Check: 382.0 - 203.95 tracked out - 45.85 - 67.04 = $65.2B other suppliers and production costs. That equals products cost of sales $194.1B minus net tracked $128.95B ($203.95B - $75B). Revenue shown here is therefore $307.0B of products net sales plus the $75.0B of buy-sell receipts.",
      sources:[{title:"Apple FY2025 Form 10-K - net sales by category and segment, products/services cost of sales, R&D and SG&A, direct 40%/indirect 60%, vendor non-trade receivables $33.18B (vendors 46% and 23%), buy-sell treatment of component sales", url:"https://www.sec.gov/Archives/edgar/data/320193/000032019325000079/aapl-20250927.htm"}, {title:"Hon Hai Precision Industry 2025 Annual Report (English), p.131 - major sales customers (Customer E NT$3,574,256M, 44.11%) and major suppliers (Vendor L NT$2,348,108M, 36.99%; NT$2,278,037M in 2024)"}, {title:"Quanta Computer 2025 Annual Report, p.123 - major customers (2025 A/B/C NT$624.3B/433.4B/315.6B; 2024 NT$441.1B/292.1B/210.9B) and consigned-material procurement"}, {title:"The Bamboo Works - Apple supplier Luxshare launches $3 billion Hong Kong IPO (2025 revenue RMB332.3B; Customer A 56.7%)", url:"https://thebambooworks.com/apple-supplier-luxshare-launches-3-billion-hong-kong-ipo/"}, {title:"Korea Herald - LG Innotek 2025 revenue KRW21.9 trillion (Jan 26, 2026)", url:"https://www.koreaherald.com/article/10663095"}, {title:"Edaily - LG Innotek single customer 77.9% of revenue, H1 2026", url:"https://en.edaily.co.kr/news/eda202608145415/"}, {title:"TechCrunch - Apple tariff costs ~$800M June quarter, ~$1.1B projected September quarter 2025", url:"https://techcrunch.com/2025/07/31/apple-projects-tariff-costs-will-hit-1.1b-next-quarter/"}]},
